################################################################################################
rm(list=ls())
setwd("G:/내 드라이브/Rrunning/HW055/")
library(xml2)
files <- list.files("AJD", pattern="\\.xml$", full.names=TRUE); dl <- list()
for(i in seq_along(files)) { txt <- paste(readLines(files[i], warn=F, encoding="UTF-8"), collapse=" "); it <- xml_find_all(read_xml(gsub("&#[xX]?[0-9a-fA-F]+;", "", txt)), "//*[front/biblioData[@type='T']]"); if(length(it)>0) dl[[i]] <- data.frame(id=xml_attr(it, "id"), t=xml_text(xml_find_first(it, ".//text/content")), stringsAsFactors=F) }
