################################################################################################
df$Pol=str_count(df$t,"叛亂|逆謀|鞫問|罷職|上疏"); df$Eco=str_count(df$t,"饑饉|凶年|賑恤|還上|貢物"); df$Soc=str_count(df$t,"盜賊|殺人|訴訟|流民|火賊"); df$Cul=str_count(df$t,"祭祀|科擧|書院|僧侶|成均館"); df$Dip=str_count(df$t,"使臣|倭寇|野人|朝貢|胡虜"); df$Nat=str_count(df$t,"地震|日食|彗星|水災|旱災"); df$Dis=str_count(df$t,"疫病|溫疫|疾疫|痘瘡|霍亂")
