df_p <- merge(as.data.frame(as.table(freq)), data.frame(Var1=c("Seoul","GG","CC","JL","GS","GW","HH","PA","HG","JJ"), lon=c(126.8, 127.5, 126.8, 127.1, 128.5, 128.3, 125.7, 125.7, 127.5, 126.5), lat=c(37.6, 37.1, 36.5, 35.5, 35.8, 37.8, 38.3, 39.5, 40.5, 33.3)))
df_dis <- df_p[df_p$Var2 == "Dis", ]; df_bar <- df_p[df_p$Var2 != "Dis", ]; df_bar$xmin <- df_bar$lon + as.numeric(factor(df_bar$Var2))*0.1 - 0.35; df_bar$xmax <- df_bar$xmin + 0.08; df_bar$ymin <- df_bar$lat; df_bar$ymax <- df_bar$lat + (df_bar$Freq / max(df_bar$Freq)) * 1.0
write.table(df_p, "Output_20260929/02_sillok_map_stats_v2.txt", sep="\t", row.names=F, fileEncoding="UTF-8")
pdf("Output_20260929/02_sillok_map_analysis_v2.pdf", width=9, height=12)
