################################################################################################
df$vol=substr(df$id,1,7); df$Pol=str_count(df$t,"叛亂|逆謀|鞫問|罷職|上疏"); df$Eco=str_count(df$t,"饑饉|凶年|賑恤|還上|貢物"); df$Soc=str_count(df$t,"盜賊|殺人|訴訟|流民|火賊"); df$Cul=str_count(df$t,"祭祀|科擧|書院|僧侶|成均館"); df$Dip=str_count(df$t,"使臣|倭寇|野人|朝貢|胡虜"); df$Nat=str_count(df$t,"地震|日食|彗星|水災|旱災"); df$Dis=str_count(df$t,"疫病|溫疫|疾疫|痘瘡|霍亂")
regs <- c("JJ","JL","GS","CC","GG","Seoul","GW","HH","PA","HG"); vars <- c("Dis","Nat","Eco","Soc","Pol","Cul","Dip"); h_list <- list(); s_list <- list(); idx <- 1
for(r in regs) { m <- rowsum(as.matrix(df[,vars])*(df[,r]>0), df$vol); td <- as.data.frame(as.table(m)); td$Region <- r; h_list[[r]] <- td; for(v in vars) { x <- m[,v]; s_list[[idx]] <- data.frame(Region=r, Variable=v, Total_Freq=sum(x), Mean_Freq=round(mean(x),2), Max_Spike=max(x), Peak_Vol=rownames(m)[which.max(x)], Active_Vols=sum(x>0), Persistence_Pct=round(mean(x>0)*100,2), Temporal_CoM=round(sum(seq_along(x)*x)/max(1,sum(x)),1), Burstiness=round((sd(x)-mean(x))/(sd(x)+mean(x)+1e-9),3), stringsAsFactors=FALSE); idx <- idx+1 } }
hov_df <- do.call(rbind, h_list); stat_df <- do.call(rbind, s_list); hov_df$Region <- factor(hov_df$Region, levels=regs); hov_df$Var2 <- factor(hov_df$Var2, levels=vars); hov_df$LogFreq <- log1p(hov_df$Freq)
write.table(stat_df, "Output_20260929/03_hovmoller_stats.txt", sep="\t", row.names=FALSE, fileEncoding="UTF-8"); write.table(hov_df, "Output_20260929/03_hovmoller_matrix.txt", sep="\t", row.names=FALSE, fileEncoding="UTF-8")
pdf("Output_20260929/03_hovmoller_diagram.pdf", width=14, height=12); print(ggplot(hov_df, aes(x=Var1, y=Region, fill=LogFreq)) + geom_tile() + facet_wrap(~Var2, ncol=1) + scale_fill_gradientn(colours=c("white","#fee090","#f46d43","#a50026"), name="log(Freq+1)") + labs(title="Spatio-Temporal Hovmoller Diagram Across Joseon Dynasty", subtitle="Latitude-ordered Regional Propagation (South to North) across Chronological Volumes", x="Chronological Volume ID", y="Region (South to North)") + theme_minimal() + theme(axis.text.x=element_text(angle=90, hjust=1, size=4), strip.text=element_text(face="bold", size=10), panel.grid=element_blank())); dev.off()



################################################################################################
